from abc import ABC, abstractmethod

# Abstract class SortAlgorithm
class SortAlgorithm(ABC):
    @abstractmethod
    def compare(self, a, b):
        pass

    @abstractmethod
    def swap(self, a, b):
        pass

    def sort(self, arr):
        raise NotImplementedError("Subclass must implement the sort method")

# Concrete class BubbleSort
class BubbleSort(SortAlgorithm):
    def compare(self, a, b):
        if a < b:
            return -1
        elif a > b:
            return 1
        else:
            return 0

    def swap(self, a, b):
        if a < b:
            a, b = b, a
        return a, b

# Concrete class SelectionSort
class SelectionSort(SortAlgorithm):
    def compare(self, a, b):
        if a < b:
            return -1
        elif a > b:
            return 1
        else:
            return 0

    def swap(self, a, b):
        if a < b:
            a, b = b, a
        return a, b

# Test the implementation
arr = [64, 34, 25, 12, 22, 11, 90]
bubble_sort = BubbleSort()
selection_sort = SelectionSort()

print("Bubble Sort:")
bubble_sort.sort(arr)
print(arr)

print("\nSelection Sort:")
selection_sort.sort(arr)
print(arr)
